(* [comment removed for export] *)

Definition mutex_lock_post (ra sp gp tp s0 s1 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (M : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a1 a2 a3 a4 a5 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz 0) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(M, M + 40)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ APMutex m' M EBUSY.

Definition mutex_lock_stmt : Prop :=
  forall (M : Z) ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  APMutex m M 0 ->
  mem_inv asegs m ->
  evt asegs (mutex_lock_post ra sp gp tp s0 s1 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc M m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz M) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_PTHREAD_MUTEX_LOCK) fc None m (seg_rom asegs)).

Lemma mutex_lock_spec : mutex_lock_stmt.
Proof.
  unfold mutex_lock_stmt.
  intros M ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m PM MI.
  destruct (PMutex_cells _ _ _ PM) as (C & _ & AL). clear PM.
  pose proof (rw_cells_bound _ _ _ _ C) as CBD. cbn [cells_size csize Nat.add] in CBD.
  pose proof (amo_aligned_M4 M ltac:(lia) ltac:(lia) AL) as AMO.
  pose proof (munch_refl [(M, M + 40)]%Z m) as MU.
  pose proof (wmono_refl asegs m) as WM.
  unfold wz, EBUSY in *. unfold P_A_PTHREAD_MUTEX_LOCK.
  (* lbu a1, 0(a0); andi a1, a1, 15: the mutex type, 0 (normal) *)
  step. step.
  (* bnez a1: not taken *)
  step. try first [if_false | if_true].
  (* addi a2, a0, 4; li a3, 16 *)
  step. step.
  (* lr.w.aqrl a4, (a2): the lock word, 0 *)
  amo_step AMO.
  (* bne a4, a1: not taken *)
  step. try first [if_false | if_true].
  (* sc.w.aqrl a5, a3, (a2): the reservation is the lr's, so the store of EBUSY succeeds *)
  amo_step AMO.
  (* bnez a5: not taken; sext.w a4, a4; beqz a4: taken *)
  step. try first [if_false | if_true].
  step.
  step. try first [if_false | if_true].
  (* mv a0, zero; ret *)
  step. step.
  finish.
  eapply PMutex_fold; [ | right; reflexivity | exact AL].
  eapply xl_cells_congr; [ | | | exact C];
    [ reflexivity | reflexivity | cbn; repeat (first [exact I | reflexivity | split]) ].
Qed.

(* [comment removed for export] *)
(* [comment removed for export] *)

Definition MUTEX_UNLOCK_STACK : Z := 96.

Definition mutex_unlock_post (ra sp gp tp s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (M lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a1 a2 a3 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz 0) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(lo, bv_unsigned sp); (M, M + 40)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ APMutex m' M 0.

Definition mutex_unlock_stmt : Prop :=
  forall (M lo : Z) ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  APMutex m M EBUSY ->
  stk asegs m lo (bv_unsigned sp) -> lo + MUTEX_UNLOCK_STACK <= bv_unsigned sp -> aceil <= lo ->
  (M + 40 <= lo \/ bv_unsigned sp <= M) ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv asegs m ->
  evt asegs (mutex_unlock_post ra sp gp tp s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc M lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz M) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_PTHREAD_MUTEX_UNLOCK) fc None m (seg_rom asegs)).

Lemma mutex_unlock_spec : mutex_unlock_stmt.
Proof.
  unfold mutex_unlock_stmt, MUTEX_UNLOCK_STACK.
  intros M lo ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m PM ST LO CE DJ RA MI.
  destruct (PMutex_cells _ _ _ PM) as (C & _ & AL). clear PM.
  pose proof (rw_cells_bound _ _ _ _ C) as CBD. cbn [cells_size csize Nat.add] in CBD.
  pose proof (amo_aligned_M4 M ltac:(lia) ltac:(lia) AL) as AMO.
  pose proof (bv_unsigned_in_range 64 sp) as SPR. unfold bv_modulus in SPR. change (2 ^ Z.of_N 64) with (2^64) in SPR.
  pose proof (munch_refl [(lo, bv_unsigned sp); (M, M + 40)]%Z m) as MU.
  pose proof (wmono_refl asegs m) as WM.
  unfold wz, EBUSY in *. unfold P_A_PTHREAD_MUTEX_UNLOCK.
  carve_frame 96%nat ST.
  (* prologue: addi sp, sp, -96 and eleven saves *)
  do 12 step.
  (* lw s4, 8(a0): waiters, 0; lwu s6, 0(a0): type, 0; andi s2; andi s1; addi s0, a0, 4 *)
  do 5 step.
  (* beqz s2: taken (normal mutex); mv a1, zero; j *)
  step. try first [if_true | if_false].
  step. step.
  (* lw a0, 0(s0): the lock word, EBUSY *)
  step.
  (* lr.w.aqrl a2, (s0) *)
  amo_step AMO.
  (* bne a2, a0: not taken *)
  step. try first [if_false | if_true].
  (* sc.w.aqrl a3, a1, (s0): the reservation is the lr's, so the store of 0 succeeds *)
  amo_step AMO.
  (* bnez a3: not taken; sext.w a2, a2; bne a2, a0: not taken *)
  step. try first [if_false | if_true].
  step.
  step. try first [if_false | if_true].
  (* snez a1, s4; slti a0, a0, 0; or s4, a1, a0 *)
  do 3 step.
  (* beqz s2: taken; beqz s4: taken (no waiters, so no futex wake) *)
  step. try first [if_true | if_false].
  step. try first [if_true | if_false].
  (* mv a0, zero; eleven restores *)
  do 12 step.
  release_frame FR ST (bv_unsigned sp).
  (* addi sp, sp, 96; ret *)
  step. step.
  finish.
  eapply PMutex_fold; [ | left; reflexivity | exact AL].
  eapply xl_cells_congr; [ | | | exact C];
    [ reflexivity | reflexivity | cbn; repeat (first [exact I | reflexivity | split]) ].
Qed.

